package registry

import (
	_ "embed"
	"encoding/json"
	"fmt"
	"sync"
)

// pythonStdlibTable is the committed table of the Python standard library's
// module names (sys.stdlib_module_names), generated by internal/registry/gen.
// PyPI blocks a project name that matches one of them.
//
//go:embed python-stdlib-modules.json
var pythonStdlibTable []byte

// PythonStdlibTable is the decoded table.
type PythonStdlibTable struct {
	Generator     string   `json:"generator"`
	Source        string   `json:"source"`
	PythonVersion string   `json:"python_version"`
	Modules       []string `json:"modules"`
}

var loadPythonStdlib = sync.OnceValues(func() (PythonStdlibTable, error) {
	var t PythonStdlibTable
	if err := json.Unmarshal(pythonStdlibTable, &t); err != nil {
		return PythonStdlibTable{}, fmt.Errorf("the embedded Python standard-library table does not decode: %w", err)
	}
	return t, nil
})

// PythonStdlib is the embedded Python standard-library table.
func PythonStdlib() PythonStdlibTable {
	t, err := loadPythonStdlib()
	if err != nil {
		// The table is compiled in; a test decodes it.
		panic(err)
	}
	return t
}

// pythonStdlibCollision is the standard-library module whose PEP 503
// normalized name equals name's, if any.
func pythonStdlibCollision(name string) (string, bool) {
	normalized := NormalizePypi(name)
	for _, m := range PythonStdlib().Modules {
		if NormalizePypi(m) == normalized {
			return m, true
		}
	}
	return "", false
}
